test("MCP start freezes explicit scope and exact retries never apply a second edit", async () => {
 const {task,selectedRefs,preparedIds,apply}=setup();
 selectedRefs.push({trackId:'ignored-ui-selection',elementId:'unselected'});
 const input={...options,elementIds:[],requestId:'mcp-request'};
 task.startRemote(input);task.startRemote(input);
 if(task.getSnapshot().status==='running') await new Promise<void>(resolve=>{
  const off=task.subscribe(()=>{if(task.getSnapshot().status!=='running'){off();resolve();}});
 });
 expect(task.getSnapshot()).toMatchObject({status:'succeeded',requestId:'mcp-request',projectId:'project',sceneId:'source'});
 task.startRemote(input);
 expect(preparedIds).toEqual([[]]);expect(apply).toHaveBeenCalledTimes(1);
 expect(()=>task.startRemote({...input,elementIds:['other']})).toThrow('different inputs');
});
